self.addEventListener("install", e => {
  // cache: "reload" — берём файлы с сервера, а не из кэша браузера (иначе новая версия могла сохранить старую страницу)
  e.waitUntil(caches.open(V).then(c => c.addAll(CORE.map(u => new Request(u, { cache: "reload" })))).then(() => self.skipWaiting()));
});
async function syncPhotos() {
  const c = await caches.open(PH);
  let meta = {};
  try { const r = await c.match(META); if (r) meta = await r.json(); } catch (e) {}
  const want = Object.keys(PHOTOS).filter(p => meta[p] !== PHOTOS[p]);
  for (let i = 0; i < want.length; i++) {
    const p = want[i];
    try { const r = await fetch(p, { cache: "no-cache" }); if (r.ok) { await c.put(p, r); meta[p] = PHOTOS[p]; } } catch (e) {}
    if (i % 50 === 49) await c.put(META, new Response(JSON.stringify(meta)));
  }
  for (const p of Object.keys(meta)) if (!(p in PHOTOS)) { await c.delete(p); delete meta[p]; }
  await c.put(META, new Response(JSON.stringify(meta)));
}
self.addEventListener("activate", e => {
  e.waitUntil(caches.keys().then(ks => Promise.all(ks.filter(k => k !== V && k !== PH).map(k => caches.delete(k)))).then(() => self.clients.claim()));
  syncPhotos();
});
self.addEventListener("message", e => { if (e.data === "sync") syncPhotos(); });
self.addEventListener("fetch", e => {
  if (e.request.method !== "GET") return;
  const u = new URL(e.request.url);
  if (u.origin !== location.origin) return;
  const path = u.pathname.slice(self.registration.scope.length - location.origin.length);
  if (path.startsWith("photos/")) {
    e.respondWith(caches.open(PH).then(c => c.match(path).then(r => r || fetch(e.request).then(n => { if (n.ok) c.put(path, n.clone()); return n; }))));
    return;
  }
  e.respondWith(caches.match(e.request, { ignoreSearch: true }).then(r => r || fetch(e.request)));
  // страница открывается из памяти мгновенно, а в фоне сверяем её с сервером; изменилась — сохраняем и говорим странице
  if (e.request.mode === "navigate" || path === "" || path === "index.html") e.waitUntil(checkFresh());
});
let lastCheck = 0;
async function checkFresh() {
  if (Date.now() - lastCheck < 30000) return;
  lastCheck = Date.now();
  try {
    const c = await caches.open(V), old = await c.match("index.html");
    const r = await fetch("index.html", { cache: "no-cache" });
    if (!r.ok) return;
    const tag = r.headers.get("etag") || r.headers.get("last-modified");
    const was = old && (old.headers.get("etag") || old.headers.get("last-modified"));
    if (!tag || tag === was) return;
    await c.put("index.html", r.clone());
    await c.put("./", r);
    (await self.clients.matchAll({ type: "window" })).forEach(w => w.postMessage("upd"));
  } catch (e) {}
}
